from typing import List
from functools import lru_cache

class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        n = len(nums)
        # Precompute adjacency: adj[i][j] = True if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
        adj = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    a, b = nums[i], nums[j]
                    if a % b == 0 or b % a == 0:
                        adj[i][j] = True

        # DP over subsets: dp[mask][last] = number of ways to form permutation ending with 'last'
        # using elements in 'mask'
        @lru_cache(maxsize=None)
        def dfs(mask: int, last: int) -> int:
            if mask == (1 << n) - 1:
                return 1
            total = 0
            for nxt in range(n):
                if not (mask >> nxt) & 1:
                    if adj[last][nxt]:
                        total += dfs(mask | (1 << nxt), nxt)
            return total

        # Start with each element as the first element
        res = 0
        for i in range(n):
            res += dfs(1 << i, i)

        return res % (10**9 + 7)
